template<class Read> bool contract(std::uintptr_t base,Read read) noexcept {
 if(!base)return false;
 unsigned char actual[128]{};
 for(const auto& pin:pins)if(!read(base+pin.rva,actual,pin.size)||std::memcmp(actual,pin.bytes,pin.size))return false;
 std::uintptr_t method=0;
 return read(base+serviceVft+0x18,&method,sizeof(method))&&method==base+methodRva;
}
// The host fixture replaces only native memory and the ABI invocation. Real
// current exact entity/combat/state/backlink validation remains in production.
template<class Read,class Call,class Validate>
const void* lookup(std::uintptr_t base,std::uint32_t id,bool exactRetail,Read read,Call call,Validate validate) noexcept {
 if(!callbackDepth||!id||!exactRetail||!contract(base,read))return nullptr;
 std::uintptr_t game=0,service=0,vft=0,method=0;
 if(!read(base+gameGlobal,&game,sizeof(game))||!game||!read(game+0x180,&service,sizeof(service))||!service||
    !read(service,&vft,sizeof(vft))||vft!=base+serviceVft||
    !read(vft+0x18,&method,sizeof(method))||method!=base+methodRva)return nullptr;
 const void* nativeActor=nullptr;
 if(!call(method,service,id,nativeActor)||!nativeActor)return nullptr;
 return validate(nativeActor,id);
}
